package com.shiphappens.logistics.controller;
import com.shiphappens.logistics.dto.Requests; import com.shiphappens.logistics.entity.*; import com.shiphappens.logistics.service.LogisticsService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class DeliveryController { private final LogisticsService service; public DeliveryController(LogisticsService service){this.service=service;} @PostMapping("/deliveries/assign") public ResponseEntity<DeliveryAssignment> assign(@Valid @RequestBody Requests.AssignDelivery request){return ResponseEntity.status(HttpStatus.CREATED).body(service.assign(request));} @PatchMapping("/deliveries/{id}/status") public DeliveryAssignment status(@PathVariable Long id,@Valid @RequestBody Requests.DeliveryStatus request){return service.updateDelivery(id,request);}@GetMapping("/drivers") public List<Driver> drivers(){return service.drivers();}@PostMapping("/drivers") public ResponseEntity<Driver> createDriver(@Valid @RequestBody Requests.Driver request){return ResponseEntity.status(HttpStatus.CREATED).body(service.createDriver(request));}@GetMapping("/vehicles") public List<Vehicle> vehicles(){return service.vehicles();}@PostMapping("/vehicles") public ResponseEntity<Vehicle> createVehicle(@Valid @RequestBody Requests.Vehicle request){return ResponseEntity.status(HttpStatus.CREATED).body(service.createVehicle(request));}@GetMapping("/warehouses") public List<Warehouse> warehouses(){return service.warehouses();}@PostMapping("/warehouses") public ResponseEntity<Warehouse> createWarehouse(@Valid @RequestBody Requests.Warehouse request){return ResponseEntity.status(HttpStatus.CREATED).body(service.createWarehouse(request));} }
